<script setup>
import { Link, useForm } from '@inertiajs/vue3';
import InternalDashboardLayout from '@/Layouts/InternalDashboardLayout.vue';
const props=defineProps({user:Object,periods:Array});
const now=new Date(); const form=useForm({bulan:now.getMonth()+1,tahun:now.getFullYear()});
const create=()=>form.post(route('dashboard.kpi.period.store'));
</script>
<template><InternalDashboardLayout title="KPI" :user="user" content-width="wide"><div class="mx-auto max-w-[1200px] p-5 sm:p-8"><div class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-3xl font-bold text-[#0a377f]">KPI Karyawan</h2><p class="mt-1 text-slate-500">Kelola periode, penilaian, dan status KPI.</p></div><form v-if="user.roleName==='super_admin'" class="flex gap-2" @submit.prevent="create"><input v-model.number="form.bulan" min="1" max="12" type="number" class="w-20 rounded-lg border-slate-300"><input v-model.number="form.tahun" min="2020" type="number" class="w-28 rounded-lg border-slate-300"><button class="rounded-lg bg-[#1463e8] px-4 py-2 font-semibold text-white">Bentuk Periode</button></form></div><div class="mt-7 overflow-x-auto"><table class="min-w-full divide-y divide-slate-200 text-sm"><thead class="bg-slate-50 text-left text-slate-500"><tr><th class="px-4 py-3">Bulan Performa</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Aksi</th></tr></thead><tbody><tr v-for="period in periods" :key="period.id" class="border-b"><td class="px-4 py-4 font-semibold">{{ period.bulan }}/{{ period.tahun }}</td><td class="px-4 py-4"><span class="rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700">{{ period.status }}</span></td><td class="px-4 py-4"><Link :href="route('dashboard.kpi.employees',period.id)" class="font-semibold text-[#1463e8]">KPI-Karyawan</Link></td></tr><tr v-if="!periods.length"><td colspan="3" class="px-4 py-10 text-center text-slate-500">Belum ada periode KPI.</td></tr></tbody></table></div></div></div></InternalDashboardLayout></template>
